function getCode(t) {
	try {
		let 验证码 = result.get("验证码（填完验证码后，要点👤登录）");
		let 账号 = result.get("账号");
		let 密码 = result.get("密码");
        if(账号 && 密码){
            try{
            java.upLoginData({
                "账号":账号,
                "密码":密码
            })
            }catch(e){
                let a = source.getLoginInfoMap();
                if(a){
                    a["账号"] = 账号;
                    a["密码"] = 密码;
                    source.putLoginInfo(JSON.stringify(a))
                }
            }
        }

		if (!/^\d{4,}/.test(验证码)) {
			let res = JSON.parse(java.ajax(getloginUrl()));
			if (res.code == "221003") {
				let url = "https://app.jjwxc.org//appDevicesecurityAndroid/getDeviceSecurityCode";
				body = "versionCode=401&username=" + encodeURIComponent(账号) + "&checktype=" + t;
				option = {
					"method": "POST",
					"body": String(body)
				}
				msg = JSON.parse(java.ajax(url + "," + JSON.stringify(option))).data.message;
				java.toast(msg);
			}  else {
                if(/校验验证码/.test(res.message)){
                    refreshToken(t);
                    return;
                }

				msg = res.message??"✅登录成功\n❗️请你删除抓包token里的值，以免被旧值覆盖\n🆕最新token值："+res.token+"\n✅无需填验证码";
			   java.longToast(msg);
			   if (/\d+_[a-z\d]+/.test(String(res.token))) {
					LoginToken(String(res.token))
				}
			}
		} else {
			refreshToken(t,验证码)
		}
	} catch (e) {
		java.log(e)
	}
}



