        result = S("$.data.content")
    }else if(S("$.data.type") == "4"){
     	  if(S("$.data.opus")){
     	  	let r = "";
     	  	let prs = JSON.parse(src).data.opus.content.paragraphs;
     	  	prs.forEach(x=>{
     	  		    switch(x.para_type){
     	  		    	    case 1:
     	  		    	         r += x.text.nodes?getNodes(x.text.nodes)+"\n":"\n"
     	  		    	         break
