            let nodes = [{}];
            nodes[0].type = "TEXT_NODE_TYPE_RICH";
            nodes[0].rich = node;
            html += getNodes(nodes);
        }) : null;

        if (orig.major) {
            html += getMajor(orig.major)
        }
        if (orig.additional) {
            html += getLinkCard(orig.additional)
        }
    }
    result = html
